const crypto = require('crypto');
const headers = $json.headers || {};
const query = $json.query || {};
const body = $json.body || {};
const initData = headers['x-telegram-init-data'] || headers['X-Telegram-Init-Data'] || query.initData || query.init_data || null;
if (!initData) throw new Error('INIT_DATA_MISSING');
const token = $env.MONEYTRACK_BOT_TOKEN;
if (!token) throw new Error('BOT_TOKEN_MISSING');
const params = {};
for (const part of initData.split('&')) { const i = part.indexOf('='); if (i < 0) continue; params[decodeURIComponent(part.slice(0,i))] = decodeURIComponent(part.slice(i+1)); }
const received = params.hash; if (!received) throw new Error('HASH_MISSING'); delete params.hash;
const check = Object.keys(params).sort().map((k) => `${k}=${params[k]}`).join('\n');
const secret = crypto.createHmac('sha256','WebAppData').update(token).digest();
const calculated = crypto.createHmac('sha256',secret).update(check).digest('hex');
if (calculated !== received) throw new Error('INVALID_INIT_DATA_HASH');
const user = JSON.parse(params.user || '{}'); if (!user.id) throw new Error('USER_MISSING');
return [{json:{telegram_user_id:user.id, query, body}}];

